/* ---------------------------------------------------------------------------
   Aamin UI — brand blue on dim navy (dark-first).
   Light theme: soft paper with the brand blue #015B91 as primary. Dark
   (default): a DIM theme — surfaces tinted with the brand navy #002F5D's
   hue (softened, never pure black), luminous light-blue primary (same hue
   as #015B91, lightened for contrast) with the brand navy on top of it.
   Hues: neutrals ~250 (cool), brand blue ~245-253.
--------------------------------------------------------------------------- */
:root {
  --background: oklch(0.977 0.003 250);
  --foreground: oklch(0.235 0.012 250);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.235 0.012 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.235 0.012 250);
  --primary: oklch(0.455 0.114 244.9); /* brand shape blue #015B91 */
  --primary-foreground: oklch(0.985 0.005 250);
  --secondary: oklch(0.945 0.006 250);
  --secondary-foreground: oklch(0.32 0.012 250);
  --muted: oklch(0.945 0.006 250);
  --muted-foreground: oklch(0.52 0.012 250);
  --accent: oklch(0.93 0.02 245);
  --accent-foreground: oklch(0.306 0.095 253.2); /* brand navy #002F5D */
  --destructive: oklch(0.55 0.19 25);
  --success: oklch(0.56 0.118 166);
  --warning: oklch(0.62 0.13 75);
  --border: oklch(0.906 0.006 250);
  --input: oklch(0.885 0.008 250);
  --ring: oklch(0.455 0.114 244.9);
  --chart-1: oklch(0.56 0.12 245);
  --chart-2: oklch(0.62 0.11 200);
  --chart-3: oklch(0.72 0.13 75);
  --chart-4: oklch(0.62 0.16 15);
  --chart-5: oklch(0.58 0.14 300);
  --radius: 0.75rem;
  --sidebar: oklch(0.955 0.004 250);
  --sidebar-foreground: oklch(0.4 0.012 250);
  --sidebar-primary: oklch(0.455 0.114 244.9);
  --sidebar-primary-foreground: oklch(0.985 0.005 250);
  --sidebar-accent: oklch(0.91 0.008 250);
  --sidebar-accent-foreground: oklch(0.235 0.012 250);
  --sidebar-border: oklch(0.906 0.006 250);
  --sidebar-ring: oklch(0.455 0.114 244.9);
}

.dark {
  --background: oklch(0.21 0.025 253); /* dim navy — brand navy hue, darkened */
  --foreground: oklch(0.93 0.008 250);
  --card: oklch(0.255 0.028 253);
  --card-foreground: oklch(0.93 0.008 250);
  --popover: oklch(0.255 0.028 253);
  --popover-foreground: oklch(0.93 0.008 250);
  --primary: oklch(0.76 0.12 245); /* brand blue hue, lightened for dark bg */
  --primary-foreground: oklch(0.306 0.095 253.2); /* brand navy #002F5D */
  --secondary: oklch(0.295 0.028 253);
  --secondary-foreground: oklch(0.9 0.008 250);
  --muted: oklch(0.295 0.028 253);
  --muted-foreground: oklch(0.78 0.014 250);
  --accent: oklch(0.32 0.05 248);
  --accent-foreground: oklch(0.88 0.07 245);
  --destructive: oklch(0.68 0.17 20);
  --success: oklch(0.82 0.15 166);
  --warning: oklch(0.8 0.13 80);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.76 0.12 245 / 60%);
  --chart-1: oklch(0.76 0.12 245);
  --chart-2: oklch(0.74 0.1 200);
  --chart-3: oklch(0.8 0.13 80);
  --chart-4: oklch(0.72 0.15 15);
  --chart-5: oklch(0.7 0.13 300);
  --sidebar: oklch(0.185 0.024 253);
  --sidebar-foreground: oklch(0.78 0.012 250);
  --sidebar-primary: oklch(0.76 0.12 245);
  --sidebar-primary-foreground: oklch(0.306 0.095 253.2);
  --sidebar-accent: oklch(0.275 0.028 253);
  --sidebar-accent-foreground: oklch(0.93 0.008 250);
  --sidebar-border: oklch(1 0 0 / 9%);
  --sidebar-ring: oklch(0.76 0.12 245 / 60%);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    scrollbar-color: color-mix(in oklab, var(--muted-foreground) 35%, transparent) transparent;
  }
  body {
    @apply bg-background text-foreground;
    @apply font-sans;
    font-feature-settings: "ss01";
  }
  ::selection {
    background: color-mix(in oklab, var(--primary) 25%, transparent);
  }

  /*
    Tailwind v4's preflight flattens `cursor` on buttons to `default`.
    Anything clickable keeps the pointer affordance (reka primitives —
    switch, checkbox, tabs trigger, select trigger… — all render <button>).
  */
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  /*
    Fields whose CONTENT is left-to-right (emails, phones, URLs, amounts —
    either .num fields or input types the browser UA stylesheet forces to
    direction:ltr) keep their LTR typing order but anchor to the right in an
    RTL page, sitting under their labels like every other field. Alignment
    utilities (e.g. text-center on PIN slots) still win — later layer.
  */
  [dir="rtl"] :where(input[type="email"], input[type="tel"], input[type="url"], input[type="number"], input.num, textarea.num) {
    direction: ltr;
    text-align: right;
  }

  /* Indeterminate progress: frozen at the inline-start under reduced motion */
  @media (prefers-reduced-motion: reduce) {
    .animate-progress-indeterminate {
      animation: none;
    }
  }
}

@utility num {
  /* Numeric text: mono, tabular, isolated LTR (amounts, SNs, phones, dates) */
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  direction: ltr;
  unicode-bidi: isolate;
}

@utility row-number {
  /* A table's "#" gutter (header + body cells): a tinted strip closed by a
     hairline on its end edge, so the row's position never reads as part of
     the figure beside it. Put the digits in a `.num` span inside the cell. */
  width: 1px;
  white-space: nowrap;
  text-align: center;
  color: var(--muted-foreground);
  background-color: color-mix(in oklab, var(--muted) 45%, transparent);
  border-inline-end: 1px solid var(--border);
}

@utility glow-primary {
  /* Luminous ring for the one primary action per view (dark shines, light stays soft) */
  box-shadow: 0 0 20px -6px color-mix(in oklab, var(--primary) 38%, transparent);
}

@utility bg-grid {
  /* Faint blueprint grid — auth panels and empty canvases */
  background-image:
    linear-gradient(color-mix(in oklab, var(--foreground) 5%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--foreground) 5%, transparent) 1px, transparent 1px);
  background-size: 32px 32px;
}

@utility bg-halo {
  /* Single soft radial glow anchored top-start */
  background-image: radial-gradient(
    56rem 32rem at 18% -8%,
    color-mix(in oklab, var(--primary) 14%, transparent),
    transparent 62%
  );
}

@utility scroll-x {
  /* Horizontal-only overflow with an indicator-style scrollbar: thin thumb,
     transparent track. Y is hidden explicitly — with overflow-x set, CSS
     computes overflow-y:visible as auto and phantom vertical bars appear. */
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--muted-foreground) 45%, transparent) transparent;

  &::-webkit-scrollbar {
    height: 4px;
  }
  &::-webkit-scrollbar-track {
    background: transparent;
  }
  &::-webkit-scrollbar-thumb {
    border-radius: 9999px;
    background: color-mix(in oklab, var(--muted-foreground) 45%, transparent);
  }
}

@utility cn-rtl-flip {
  /* Mirrors directional glyphs (chevrons/arrows) when the tree is RTL */
  &:where(:dir(rtl), [dir="rtl"] *) {
    transform: scaleX(-1);
  }
}

@keyframes cn-shake {
  10%,
  90% {
    transform: translateX(-1px);
  }
  20%,
  80% {
    transform: translateX(2px);
  }
  30%,
  50%,
  70% {
    transform: translateX(-4px);
  }
  40%,
  60% {
    transform: translateX(4px);
  }
}

@utility cn-shake {
  /* Rejected-PIN feedback (PinConfirm). No-op under reduced motion — the
     destructive border already applied via aria-invalid on the slots is
     the sole error signal in that case. */
  animation: cn-shake 0.4s ease-in-out;

  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
}

